/* ---- offer buttons preselect the inquiry subject; UTM/source kept for attribution ---- */
  var qs=new URLSearchParams(location.search),interest=document.getElementById('f-interest'),iline=document.getElementById('interest-line'),ival=document.getElementById('interest-val');
  function setInterest(t){if(!t)return;interest.value=t;ival.textContent=t;iline.hidden=(t==='Free assessment');}
  document.querySelectorAll('[data-interest]').forEach(function(a){a.addEventListener('click',function(){setInterest(a.getAttribute('data-interest'));});});
  setInterest(qs.get('interest'));
  if(qs.get('ref'))document.getElementById('f-ref').value=qs.get('ref');
  var src=['utm_source','utm_medium','utm_campaign'].map(function(k){return qs.get(k)?k+'='+qs.get(k):'';}).filter(Boolean).join('&');
  /* ---- form: success is shown only after the server confirms receipt ---- */
  var emailRe=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  document.getElementById('intake').addEventListener('submit',function(e){
    e.preventDefault();
    var done=document.getElementById('done');done.hidden=true;done.className='done';
    var need=['f-name','f-biz','f-contact'].map(function(id){return document.getElementById(id);}).filter(function(el){el.removeAttribute('aria-invalid');var ok=el.value.trim()&&(el.id!=='f-contact'||emailRe.test(el.value.trim()));return !ok;});
    if(need.length){need.forEach(function(el){el.setAttribute('aria-invalid','true');});need[0].focus();done.className='done err';done.textContent='Please check the highlighted fields. A name, business name and valid email are needed.';done.hidden=false;return;}
    var v=function(id){return document.getElementById(id).value.trim();};
    var btn=e.target.querySelector('button[type=submit]'),label=btn.textContent;
    var body='Name: '+v('f-name')+'\nBusiness: '+v('f-biz')+'\nEmail: '+v('f-contact')+'\nWebsite: '+v('f-site')+'\nInterested in: '+v('f-interest')+'\nTiming: '+v('f-when')+'\nBudget: '+v('f-budget')+'\nReferred by: '+v('f-ref')+'\nSource: '+(src||'direct')+'\n\nWhat they would like to improve:\n'+v('f-pain');
    btn.disabled=true;btn.textContent='Sending...';
    /* copy the lead into the HubSpot CRM (best effort; the email below is the source of truth) */
    try{
      var hutk=(document.cookie.match(/hubspotutk=([^;]+)/)||[])[1];
      var hs=[['firstname',v('f-name')],['company',v('f-biz')],['website',v('f-site')],['email',v('f-contact')],['message','Interested in: '+v('f-interest')+'\nTiming: '+v('f-when')+'\nBudget: '+v('f-budget')+'\nReferred by: '+v('f-ref')+'\nSource: '+(src||'direct')+'\n\n'+v('f-pain')]]
        .filter(function(x){return x[1];}).map(function(x){return {objectTypeId:'0-1',name:x[0],value:x[1]};});
      var ctx={pageUri:location.href,pageName:document.title};if(hutk)ctx.hutk=hutk;
      fetch('https://api.hsforms.com/submissions/v3/integration/submit/247871007/41028eeb-eade-4ad2-af4f-d77729628ba6',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fields:hs,context:ctx})}).catch(function(){});
    }catch(err){}
    /* also save the lead in the MLP database (best effort) */
    try{
      fetch('https://oardvirqbbawklqvwwxc.supabase.co/rest/v1/leads',{method:'POST',headers:{'Content-Type':'application/json',apikey:'sb_publishable_Ok4J_FZyuLzHinQ910ktjg_ZD6NgTKo',Prefer:'return=minimal'},body:JSON.stringify({name:v('f-name'),business:v('f-biz'),industry:'',website:v('f-site'),contact:v('f-contact'),referred_by:v('f-ref'),pain:('Interested in: '+v('f-interest')+(src?' ['+src+']':'')+(v('f-when')?'\nTiming: '+v('f-when'):'')+(v('f-budget')?'\nBudget: '+v('f-budget'):'')+'\n'+v('f-pain')).trim(),source:'website'})}).catch(function(){});
    }catch(err){}
    fetch('https://api.web3forms.com/submit',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({access_key:'c3cd3264-8d14-478c-ba2a-afb3df8e7b03',subject:'Free assessment: '+v('f-biz')+' ('+v('f-interest')+')',from_name:'MLP Consulting site',name:v('f-name'),email:v('f-contact'),message:body})})
      .then(function(r){return r.json();})
      .then(function(j){if(!j.success)throw new Error('fail');e.target.reset();setInterest('Free assessment');btn.textContent='Request sent';done.className='done';done.textContent='Thanks, your request is in. I’ll review your business and send your assessment within one business day.';done.hidden=false;})
      .catch(function(){btn.disabled=false;btn.textContent=label;done.className='done err';done.innerHTML='That did not go through. Please email <a href="mailto:myles@mlpconsults.com">myles@mlpconsults.com</a> directly and I will pick it up from there.';done.hidden=false;});
  });
